import numpy as np

def percentile(values, p):
    s = sorted(values)
    pos = (len(s) - 1) * p / 100
    lo = int(pos)
    if lo + 1 >= len(s):
        return s[-1]
    return s[lo] + (pos - lo) * (s[lo + 1] - s[lo])

x = [12, 7, 30, 18, 25, 9, 41, 15]
mine = [round(percentile(x, p), 2) for p in (10, 50, 95)]
for v in mine:
    print(v)
print(mine == [round(float(np.percentile(x, p)), 2) for p in (10, 50, 95)])
